import{_ as g,C as c,o as a,c as A,a2 as r,b as l,w as t,a as o,E as i,a3 as s,j as n}from"./chunks/framework.mqZn2l2k.js";const h="/n8n-book/assets/fig-01-spectrum.OuGLfc8k.svg",T=JSON.parse('{"title":"第 1 章 从自动化到 AI Agent：Workflow 平台的几种形态","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/01-forms.md","filePath":"chapters/01-forms.md","lastUpdated":1791458539000}'),p={name:"chapters/01-forms.md"};function m(u,e,f,_,E,b){const d=c("Mermaid");return a(),A("div",null,[e[3]||(e[3]=r('<h1 id="第-1-章-从自动化到-ai-agent-workflow-平台的几种形态" tabindex="-1">第 1 章 从自动化到 AI Agent：Workflow 平台的几种形态 <a class="header-anchor" href="#第-1-章-从自动化到-ai-agent-workflow-平台的几种形态" aria-label="Permalink to &quot;第 1 章 从自动化到 AI Agent：Workflow 平台的几种形态&quot;">​</a></h1><blockquote><p>本章目标：读完你能区分“确定性工作流”和“Agent”，并能说出 n8n 用哪些节点实现了每一种形态。前置：第 0 章。对应代码：无</p></blockquote><h2 id="_1-问题与概念" tabindex="-1">1. 问题与概念 <a class="header-anchor" href="#_1-问题与概念" aria-label="Permalink to &quot;1. 问题与概念&quot;">​</a></h2><p>“AI Agent Workflow”这个词把两件看起来相反的事放在了一起：</p><ul><li><strong>Workflow（工作流）</strong>：步骤是 <strong>人</strong> 事先画好的。同样的输入，总是走同样的路径。可预测、可审计、便宜。</li><li><strong>Agent（智能体）</strong>：步骤是 <strong>模型</strong> 在运行时决定的。模型看到任务和一组工具，自己决定下一步调用哪个工具、调用几次、什么时候停。灵活，但不可预测、更贵。</li></ul><p>真实的系统几乎都在两者之间。n8n 的做法是：<strong>把 Agent 当成工作流里的一个节点</strong>。外层的触发、预处理、通知、错误处理仍然是确定性的工作流；只有“需要判断”的那一段交给 Agent。</p><p><img src="'+h+'" alt="从确定性工作流到自主 Agent 的光谱"></p><p><em>图 1-1：从左到右，控制权从人画好的图逐渐移交给模型。n8n 在同一张画布上覆盖了整个光谱。</em></p><p>下面按从左到右的顺序看五种形态。</p><h3 id="_1-1-形态一-触发-→-动作-trigger–action" tabindex="-1">1.1 形态一：触发 → 动作（Trigger–Action） <a class="header-anchor" href="#_1-1-形态一-触发-→-动作-trigger–action" aria-label="Permalink to &quot;1.1 形态一：触发 → 动作（Trigger–Action）&quot;">​</a></h3><p>最早的自动化产品（IFTTT、Zapier 的早期形态）只有一条直线：<strong>某事发生 → 做某事</strong>。</p>',11)),(a(),l(s,null,{default:t(()=>[i(d,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20T%5BWebhook%20%E8%A7%A6%E5%8F%91%3Cbr%2F%3E%E6%94%B6%E5%88%B0%E6%96%B0%E8%AE%A2%E5%8D%95%5D%20--%3E%20A%5BHTTP%20Request%3Cbr%2F%3E%E5%86%99%E5%85%A5%20CRM%5D%20--%3E%20S%5BSlack%3Cbr%2F%3E%E9%80%9A%E7%9F%A5%E9%94%80%E5%94%AE%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=n("p",null,[o("在 n8n 里，每个流程都从一个 "),n("strong",null,"触发器节点（trigger）"),o(" 开始：Manual Trigger（手动点按钮）、Webhook、Schedule Trigger（定时）、各种应用的事件触发（Gmail、GitHub……）。触发器产出第一批数据，后面的节点逐个处理。")],-1)),e[5]||(e[5]=n("h3",{id:"_1-2-形态二-有分支、合并、循环的-dag",tabindex:"-1"},[o("1.2 形态二：有分支、合并、循环的 DAG "),n("a",{class:"header-anchor",href:"#_1-2-形态二-有分支、合并、循环的-dag","aria-label":'Permalink to "1.2 形态二：有分支、合并、循环的 DAG"'},"​")],-1)),e[6]||(e[6]=n("p",null,"现实的业务逻辑需要判断和汇总：",-1)),(a(),l(s,null,{default:t(()=>[i(d,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20LR%0A%20%20T%5BWebhook%5D%20--%3E%20C%7BIf%3Cbr%2F%3E%E9%87%91%E9%A2%9D%20%E2%89%A5%20100%3F%7D%0A%20%20C%20--%20true%20--%3E%20V%5BSet%3A%20VIP%5D%0A%20%20C%20--%20false%20--%3E%20N%5BSet%3A%20%E6%99%AE%E9%80%9A%5D%0A%20%20V%20--%3E%20M%5BMerge%5D%0A%20%20N%20--%3E%20M%0A%20%20M%20--%3E%20R%5B%E6%B1%87%E6%80%BB%E5%B9%B6%E5%9B%9E%E5%A4%8D%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=r('<p>这里出现了 n8n 数据模型最重要的特点：节点之间传递的不是“一个值”，而是 <strong>一组 item</strong>。If 节点会把 3 个订单拆成两组，分别送到两个分支；Merge 节点再把两组合起来。第 4 章和第 7 章会详细讲这背后的执行机制。</p><p>n8n 的图还允许 <strong>环</strong>：Loop Over Items 节点把一批数据分成小批，循环处理，处理完再从 <code>done</code> 输出出去。所以严格说它不是 DAG，引擎要能处理“一个节点运行多次”。</p><h3 id="_1-3-形态三-在步骤里调用-llm-chain" tabindex="-1">1.3 形态三：在步骤里调用 LLM（Chain） <a class="header-anchor" href="#_1-3-形态三-在步骤里调用-llm-chain" aria-label="Permalink to &quot;1.3 形态三：在步骤里调用 LLM（Chain）&quot;">​</a></h3><p>把 LLM 当作一个“很聪明的函数”放到流程中间：分类、摘要、抽取字段、翻译。流程的形状没变，只是某个节点的实现换成了模型调用。</p><p>n8n 里对应的是 <strong>Basic LLM Chain</strong>、<strong>Text Classifier</strong>、<strong>Information Extractor</strong>、<strong>Summarization Chain</strong> 等节点（都在 <code>packages/@n8n/nodes-langchain/nodes/chains/</code>）。</p><h3 id="_1-4-形态四-workflow-里的-agent" tabindex="-1">1.4 形态四：Workflow 里的 Agent <a class="header-anchor" href="#_1-4-形态四-workflow-里的-agent" aria-label="Permalink to &quot;1.4 形态四：Workflow 里的 Agent&quot;">​</a></h3><p>当步骤数量和顺序无法事先确定时，就需要 Agent。例如“用户在聊天框里问：上周哪个客户下单最多？给他发一封感谢邮件”——要查数据库还是查 CRM？要不要先算一下？由模型决定。</p>',7)),(a(),l(s,null,{default:t(()=>[i(d,{id:"mermaid-76",class:"mermaid",graph:"flowchart%20LR%0A%20%20CT%5BChat%20Trigger%5D%20--%3E%20AG%5BAI%20Agent%5D%0A%20%20M1%5BOpenAI%20Chat%20Model%5D%20-.%20ai_languageModel%20.-%3E%20AG%0A%20%20ME%5BSimple%20Memory%5D%20-.%20ai_memory%20.-%3E%20AG%0A%20%20T1%5BPostgres%20Tool%5D%20-.%20ai_tool%20.-%3E%20AG%0A%20%20T2%5BCalculator%5D%20-.%20ai_tool%20.-%3E%20AG%0A%20%20T3%5BGmail%20Tool%5D%20-.%20ai_tool%20.-%3E%20AG%0A%20%20AG%20--%3E%20OUT%5B%E5%9B%9E%E5%A4%8D%E7%94%A8%E6%88%B7%5D%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[o(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=r('<p>注意图里的虚线。在 n8n 里，模型、记忆、工具 <strong>也是节点</strong>，它们通过特殊类型的连接（<code>ai_languageModel</code>、<code>ai_memory</code>、<code>ai_tool</code>）挂在 Agent 节点下面。n8n 把这种“一个根节点 + 一组子节点”的结构叫 <strong>Cluster Node</strong>。第 16 章会讲它的设计，第 18、19 章讲 Agent 如何在引擎中运行。</p><h3 id="_1-5-形态五-多-agent-与人在回路" tabindex="-1">1.5 形态五：多 Agent 与人在回路 <a class="header-anchor" href="#_1-5-形态五-多-agent-与人在回路" aria-label="Permalink to &quot;1.5 形态五：多 Agent 与人在回路&quot;">​</a></h3><p>更复杂的系统里：</p><ul><li><strong>Agent as Tool</strong>：一个“主管” Agent 把另一个 Agent 当成工具调用（n8n 的 <code>AI Agent Tool</code> 节点）。</li><li><strong>Workflow as Tool</strong>：把整个子工作流包装成一个工具（<code>Call n8n Workflow Tool</code>），让 Agent 能调用一段确定性的流程。</li><li><strong>Human in the Loop（HITL）</strong>：Agent 想执行敏感操作（发邮件、付款）前，先停下来等人批准。n8n 用“等待（waiting）”状态实现：执行被保存到数据库，等人点击批准链接后再恢复。</li><li><strong>MCP</strong>：通过 Model Context Protocol，n8n 可以调用外部 MCP 服务器提供的工具（MCP Client Tool），也可以把自己的工作流暴露成 MCP 工具（MCP Server Trigger）。</li></ul><p>这些在第 20、23、24 章展开。</p><h2 id="_2-n8n-是怎么做的-同一个引擎-不同的节点" tabindex="-1">2. n8n 是怎么做的：同一个引擎，不同的节点 <a class="header-anchor" href="#_2-n8n-是怎么做的-同一个引擎-不同的节点" aria-label="Permalink to &quot;2. n8n 是怎么做的：同一个引擎，不同的节点&quot;">​</a></h2><p>上面五种形态，在 n8n 里 <strong>共用同一个执行引擎</strong>（<code>packages/core/src/execution-engine/workflow-execute.ts</code>）。差别只在节点上：</p><table tabindex="0"><thead><tr><th>形态</th><th>代表节点</th><th>节点类型名</th><th>源码位置</th></tr></thead><tbody><tr><td>触发器</td><td>Manual Trigger、Webhook、Schedule</td><td><code>n8n-nodes-base.manualTrigger</code> 等</td><td><code>packages/nodes-base/nodes/ManualTrigger/</code> 等</td></tr><tr><td>数据变换</td><td>Edit Fields (Set)、Code</td><td><code>n8n-nodes-base.set</code>、<code>n8n-nodes-base.code</code></td><td><code>packages/nodes-base/nodes/Set/</code>、<code>Code/</code></td></tr><tr><td>流程控制</td><td>If、Switch、Merge、Loop Over Items、Wait</td><td><code>n8n-nodes-base.if</code> 等</td><td><code>packages/nodes-base/nodes/If/</code> 等</td></tr><tr><td>LLM Chain</td><td>Basic LLM Chain</td><td><code>@n8n/n8n-nodes-langchain.chainLlm</code></td><td><code>packages/@n8n/nodes-langchain/nodes/chains/ChainLLM/</code></td></tr><tr><td>Agent</td><td>AI Agent</td><td><code>@n8n/n8n-nodes-langchain.agent</code></td><td><code>packages/@n8n/nodes-langchain/nodes/agents/Agent/</code></td></tr><tr><td>子节点</td><td>Chat Model、Memory、Tool</td><td><code>...lmChatOpenAi</code>、<code>...memoryBufferWindow</code>、<code>...toolCalculator</code></td><td><code>packages/@n8n/nodes-langchain/nodes/</code> 下各目录</td></tr></tbody></table><p>在本书参照的版本里，<code>packages/nodes-base</code> 注册了 445 个节点和 412 种凭证，<code>packages/@n8n/nodes-langchain</code> 注册了 125 个 AI 节点（数自各自 <code>package.json</code> 的 <code>n8n.nodes</code> 字段）。</p><p>这张表透露了 n8n 的一个关键设计取舍：<strong>Agent 没有自己的运行时，它借用了工作流引擎</strong>。好处是：</p><ul><li>Agent 调工具的每一步都会作为节点运行记录下来，能在画布上看到、能调试、能 pin 数据。</li><li>工具可以是任何节点，Agent 自动获得了几百种集成。</li><li>错误处理、重试、超时、队列模式、权限，这些工作流已有的能力，Agent 全部继承。</li></ul><p>代价是：Agent 的循环必须适配引擎的“栈式调度”，这就是第 19 章要讲的 <code>EngineRequest</code> 机制，也是 n8n Agent 实现里最巧妙的部分。</p><h2 id="_3-从零实现-mini-n8n-要覆盖哪些形态" tabindex="-1">3. 从零实现：mini-n8n 要覆盖哪些形态 <a class="header-anchor" href="#_3-从零实现-mini-n8n-要覆盖哪些形态" aria-label="Permalink to &quot;3. 从零实现：mini-n8n 要覆盖哪些形态&quot;">​</a></h2><p>mini-n8n 不追求节点数量，只追求 <strong>每种形态至少有一个能跑的例子</strong>：</p><table tabindex="0"><thead><tr><th>形态</th><th>mini-n8n 的节点</th><th>版本</th></tr></thead><tbody><tr><td>触发器</td><td>Manual Trigger、Webhook、Schedule Trigger、Chat Trigger</td><td>v0.1 / v0.2 / v0.4</td></tr><tr><td>变换与控制</td><td>Set、Code、If、Merge、Loop Over Items、Split Out、Aggregate、Wait</td><td>v0.1</td></tr><tr><td>外部调用</td><td>HTTP Request</td><td>v0.1</td></tr><tr><td>LLM</td><td>Chat Model（Mock / Ollama / OpenAI 兼容）、Basic LLM Chain</td><td>v0.4</td></tr><tr><td>Agent</td><td>AI Agent、Calculator / Code / HTTP / Workflow 工具、Simple Memory</td><td>v0.4</td></tr><tr><td>高级 AI</td><td>向量存储、Embeddings、Agent Tool、人工审批工具、结构化输出</td><td>v0.5</td></tr><tr><td>平台</td><td>Execute Workflow（子工作流）、队列模式</td><td>v1.0</td></tr></tbody></table><h2 id="_4-运行与验证" tabindex="-1">4. 运行与验证 <a class="header-anchor" href="#_4-运行与验证" aria-label="Permalink to &quot;4. 运行与验证&quot;">​</a></h2><p>本章没有代码。请在 n8n 里亲手搭一下 1.2 节的工作流（用 Code 节点造 3 个订单），执行后点开 If 节点，看看 true / false 两个输出分别有几个 item。第 4 章会用同一个例子讲数据模型。</p><h2 id="_5-练习" tabindex="-1">5. 练习 <a class="header-anchor" href="#_5-练习" aria-label="Permalink to &quot;5. 练习&quot;">​</a></h2><ol><li><strong>巩固</strong>：用自己的话解释“Workflow”和“Agent”的区别，各举一个适合的业务场景。</li><li><strong>扩展</strong>：如果一个客服机器人需要“退款金额超过 1000 元时必须人工批准”，你会把哪部分做成确定性工作流，哪部分交给 Agent？画出你的设计。</li><li><strong>读源码</strong>：打开 <code>packages/@n8n/nodes-langchain/package.json</code>，在 <code>n8n.nodes</code> 列表里找出所有以 <code>tools/</code> 开头的条目，数一数 n8n 内置了多少个 AI 工具节点。</li></ol><h2 id="_6-延伸阅读" tabindex="-1">6. 延伸阅读 <a class="header-anchor" href="#_6-延伸阅读" aria-label="Permalink to &quot;6. 延伸阅读&quot;">​</a></h2><ul><li>Anthropic, <em>Building effective agents</em>（2024）：区分 workflow 和 agent 的经典文章。</li><li>n8n 文档：<em>Advanced AI</em> 章节，介绍 Cluster Node、Root Node、Sub-node 的概念。</li><li><code>packages/@n8n/nodes-langchain/nodes/agents/Agent/Agent.node.ts</code>：AI Agent 节点的版本入口。</li></ul>',21))])}const C=g(p,[["render",m]]);export{T as __pageData,C as default};
